def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
    if not cells:
        return out
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    colors = {grid[r][c] for r, c in cells}
    # The inner color is the nonzero color distinct from the rectangular frame color.
    counts = {v: sum(grid[r][c] == v for r, c in cells) for v in colors}
    inner = min(colors, key=lambda v: counts[v])
    # Extend the inset pattern's inner color two cells beyond the original object's bbox.
    for r in range(max(0, r0 - 2), min(len(grid), r1 + 3)):
        for c in range(max(0, c0 - 2), min(len(grid[0]), c1 + 3)):
            if grid[r][c] == 0:
                out[r][c] = inner
    return out

